import { useEffect, useState } from "react";
import axios from "axios";

export default function Courses() {
  const [courses, setCourses] = useState([]);
  const [quiz, setQuiz] = useState([]);
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [difficulty, setDifficulty] = useState("easy");
  const [weakTopics, setWeakTopics] = useState([]);
  const [studyPlan, setStudyPlan] = useState("");

 useEffect(() => {
  axios
    .get("/api/students/1/enrollments")
    .then((res) => {
      console.log("COURSES DATA:", res.data); // 🔥 DEBUG
      setCourses(res.data);
    })
    .catch((err) => console.log(err));
}, []);

  const generateQuiz = async () => {
    const res = await axios.get(
      `/api/quiz/generate/DBMS?difficulty=${difficulty}`
    );

    if (Array.isArray(res.data.quiz)) {
      setQuiz(res.data.quiz);
    } else {
      console.log("Invalid quiz format:", res.data.quiz);
      setQuiz([]);
    }

    setAnswers({});
    setSubmitted(false);
    setWeakTopics([]);
    setStudyPlan("");
  };

  const handleSelect = (qIndex, optionIndex) => {
    setAnswers({ ...answers, [qIndex]: optionIndex });
  };

  const submitQuiz = async () => {
    setSubmitted(true);

    const calculatedScore = quiz.reduce((acc, q, i) => {
      return acc + (answers[i] === q.answerIndex ? 1 : 0);
    }, 0);

    const weak = quiz
      .map((q, i) => ({
        question: q.question,
        correct: answers[i] === q.answerIndex,
      }))
      .filter((q) => !q.correct)
      .map((q) => {
        const text = q.question.toLowerCase();
        if (text.includes("normalization")) return "Normalization";
        if (text.includes("sql")) return "SQL";
        if (text.includes("index")) return "Indexing";
        if (text.includes("dbms")) return "DBMS basics";
        return "General DBMS";
      });

const uniqueWeak = [...new Set(weak)];
setWeakTopics(uniqueWeak);
    try {
      await axios.post("/api/quiz/weak", {
        weakTopics: weak,
      });

      await axios.post("/api/progress", {
        score: calculatedScore,
        total: quiz.length,
        weakTopics: weak,
      });
    } catch (err) {
      console.log("Error sending data", err);
    }
  };

  const score = quiz.reduce((acc, q, i) => {
    return acc + (answers[i] === q.answerIndex ? 1 : 0);
  }, 0);

  return (
    <div className="p-6">
      <h1 className="text-xl font-bold mb-4">My Courses</h1>

      <select
        value={difficulty}
        onChange={(e) => setDifficulty(e.target.value)}
        className="border px-3 py-2 rounded mb-4 mr-2"
      >
        <option value="easy">Easy</option>
        <option value="medium">Medium</option>
        <option value="hard">Hard</option>
      </select>

      <button
        onClick={generateQuiz}
        className="bg-green-500 text-white px-4 py-2 rounded mb-4"
      >
        Generate AI Quiz
      </button>

      {quiz.map((q, i) => (
        <div key={i} className="mb-6 border p-4 rounded bg-white">
          <h2 className="font-semibold mb-2">
            Q{i + 1}. {q.question}
          </h2>

          {q.options.map((opt, j) => (
            <label key={j} className="block">
              <input
                type="radio"
                name={`q-${i}`}
                disabled={submitted}
                checked={answers[i] === j}
                onChange={() => handleSelect(i, j)}
              />
              <span className="ml-2">{opt}</span>
            </label>
          ))}

          {submitted && (
            <div className="mt-2">
              {answers[i] === q.answerIndex ? (
                <p className="text-green-600 font-semibold">
                  Correct ✅
                </p>
              ) : (
                <>
                  <p className="text-red-600 font-semibold">
                    Wrong ❌ (Correct: {q.options[q.answerIndex]})
                  </p>
                  <p className="text-gray-600 text-sm">
                    {q.explanation}
                  </p>
                </>
              )}
            </div>
          )}
        </div>
      ))}

      {quiz.length > 0 && !submitted && (
        <button
          onClick={submitQuiz}
          className="bg-blue-500 text-white px-4 py-2 rounded"
        >
          Submit Quiz
        </button>
      )}

      {submitted && (
        <h2 className="mt-4 text-lg font-bold">
          Score: {score} / {quiz.length}
        </h2>
      )}

      {submitted && weakTopics.length > 0 && (
        <div className="mt-4 p-4 bg-yellow-50 border rounded">
          <h3 className="font-semibold text-yellow-700">
            Weak Areas:
          </h3>

          <ul className="list-disc ml-5 text-sm text-gray-700">
            {weakTopics.map((topic, i) => (
              <li key={i}>{topic}</li>
            ))}
          </ul>

          <button
            onClick={async () => {
              const res = await axios.get("/api/quiz/generate/weak");

              if (Array.isArray(res.data.quiz)) {
                setQuiz(res.data.quiz);
              }

              setAnswers({});
              setSubmitted(false);
              setWeakTopics([]);
              setStudyPlan("");
            }}
            className="bg-purple-500 text-white px-4 py-2 rounded mt-3"
          >
            Generate Weak Area Quiz
          </button>

          {/* ✅ FIXED HERE */}
          <button
            onClick={async () => {
              const res = await axios.post(
                "http://localhost:5000/api/study",
                { weakTopics }
              );
              setStudyPlan(res.data.plan);
            }}
            className="bg-indigo-500 text-white px-4 py-2 rounded mt-3 ml-2"
          >
            Generate Study Plan
          </button>

         {studyPlan && (
  <div className="mt-4 p-5 bg-white border shadow rounded">
    {studyPlan.split("\n").map((line, index) => {
      
      // Heading (Day 1, Day 2, etc.)
      if (line.toLowerCase().includes("day")) {
        return (
          <h3 key={index} className="font-bold text-lg mt-3">
            {line.replace(/[#*]/g, "")}
          </h3>
        );
      }

      // Bullet points
      if (line.trim().startsWith("-")) {
        return (
          <p key={index} className="ml-4 text-gray-700">
            • {line.replace("-", "").trim()}
          </p>
        );
      }

      // Normal text
      return (
        <p key={index} className="text-gray-800">
          {line.replace(/[#*]/g, "")}
        </p>
      );
    })}
  </div>
)}
        </div>
      )}
    </div>
  );
}
